interface Events { check: { checked: boolean }; submit: void }
export class Hub<E> {
  private handlers = new Map<keyof E, Array<(p: E[keyof E]) => void>>();
  on<K extends keyof E>(event: K, fn: (p: E[K]) => void): void {
    this.handlers.set(event, [...(this.handlers.get(event) ?? []), fn as (p: E[keyof E]) => void]); }
  emit<K extends keyof E>(event: K, payload: E[K]): void {
    for (const fn of this.handlers.get(event) ?? []) fn(payload); }
}
const hub = new Hub<Events>();     // created per composition, injected
hub.on('check', ({ checked }) => { email.disabled = checked; });
hub.emit('check', { checked: true });
